from datetime import datetime, timezone

def hydrate_time(nanoseconds, tz=None):
    if not (nanoseconds >= 0 and nanoseconds < 1000000000000000):
        raise ValueError("nanoseconds must be between 0 and 999999999999999")
    if tz and not isinstance(tz, timezone):
        raise ValueError("tz must be a timezone instance")

    # Convert nanoseconds to seconds
    seconds = nanoseconds / 1000000000

    # Create a datetime object
    dt = datetime(1970, 1, 1, tzinfo=timezone.utc) + seconds

    if tz:
        return dt.astimezone(tz)
    else:
        return dt

def hydrate_time(nanoseconds, tz=None):
    from datetime import datetime
    return datetime.fromtimestamp(nanoseconds / (10 ** 9), tz=tz)

