def _legacy_mergeOrderings(orderings):
    # List to store merged result
    merged_order = []
    # Dictionary to keep track of the last occurrence of each element in an ordering
    last_occurrence = {}

    # First iteration to find the maximum value in each ordering
    for ordering in orderings:
        for value in ordering:
            last_occurrence[value] = max(last_occurrence.get(value, 0), ordering.index(value))

    # Second iteration to merge the orderings
    for ordering in orderings:
        for value in ordering:
            if value in last_occurrence:
                merged_order.append(value)
                last_occurrence[value] += 1

    return merged_order

