def minimalBases(classes):
    # Ensure classes is a list of base classes
    if not isinstance(classes, list) or not all(isinstance(cl, type) for cl in classes):
        raise ValueError("Input should be a list of base classes")

    # Use a recursive function to group classes
    def group_classes(cls_list):
        if not cls_list:
            return []

        # Recursively group classes in subclasses
        grouped_list = []
        for base in cls_list:
            if base.__subclasses__():
                grouped_list.extend(group_classes(base.__subclasses__()))
            else:
                grouped_list.append(base)

        # Group by the order of appearance
        grouped_list.sort(key=lambda x: x.mro(), reverse=True)

        return grouped_list

    # Group the classes
    sorted_classes = group_classes(classes)

    # Collect unique classes
    result_classes = set()
    for cls in sorted_classes:
        base_classes = tuple(c.__name__ for c in cls.mro())
        result_classes.add(base_classes)

    return list(result_classes)

