def _explore_folder(folder):
    import os
    import re
    from collections import defaultdict

    # Validate the input parameter
    if not isinstance(folder, str):
        raise ValueError("Parameter 'folder' must be a string")

    # Walk through the directory and collect files
    package_files = defaultdict(list)
    for root, _, filenames in os.walk(folder):
        for filename in filenames:
            file_path = os.path.join(root, filename)
            with open(file_path, 'r', encoding='utf-8') as f:
                content = f.read()
                basename = os.path.basename(file_path)
                if basename.endswith('.xml'):
                    package_files[basename].append(content)

    # Filter files based on XML basename pattern
    filtered_contents = defaultdict(list)
    for basename, contents in package_files.items():
        match = re.match(r'^\w+-\d+', basename)
        if match:
            filtered_contents[match.group()].extend(contents)

    # Return the data in dict format
    return dict(filtered_contents)

