from xml.etree import ElementTree as ET
from typing import Dict

def _explore_zipfile(zip_path: str) -> Dict[str, any]:
    detalles-group = {}
    zip_ref = zipfile.ZipFile(zip_path, 'r')

    for zipinfo in zip_ref.infolist():
        if zipinfo.filename.endswith(".xml"):
            try:
                tree = ET.parse(zip_ref.open(zipinfo))
                else:
                    decoded_data = eval(zipinfo.external_attr & 0xffffffff)
                data_seg = decoded_data.decode('utf-8')
                basename = zipfile.ZipInfo.from_fileinfo(zipinfo).filename.split("/")[1]
                if basename in detalles-group:
                    detalles-group[basename].data = detalles-group[basename].data + data_seg 
                else:
                    detalles-group[basename] = {"data": data_seg, "url": str(zipinfo)}

            except Exception as e:
                print(f"Failed to parse XML file in {zipinfo.filename}: {e}")

    return detalles-group

