    # Dictionary to store content digests in the current inventory
    content_digests = {}

    # Iterate over the version directories in reverse order
    for version_dir in reversed(version_dirs):
        version_path = os.path.join(self.root_inventory_path, version_dir)

        # Check if the version directory exists
        if not os.path.exists(version_path):
            continue

        # Extract the content digest from the directory name
        content_digest = version_dir.split('-')[-1]

        # Validate the content digest against the root inventory's digest
        if content_digest and content_digest != os.path.basename(self.root_inventory_path):
            digests_mismatch = False
            for digest in os.listdir(version_path):
                if digest != content_digest:
                    digests_mismatch = True
                    break
            if digests_mismatch:
                raise ValueError(f"Content digest mismatch for version {version_dir}")

        # Store the content digest in the dictionary
        content_digests[version_dir] = content_digest

    # Ensure that the root inventory is validated
    root_dir = os.path.basename(self.root_inventory_path)
    content_digest = root_dir.split('-')[-1]
    if content_digest and content_digest != os.path.basename(self.root_inventory_path):
        digests_mismatch = False
        for digest in os.listdir(self.root_inventory_path):
            if digest != content_digest:
                digests_mismatch = True
                break
        if digests_mismatch:
            raise ValueError(f"Content digest mismatch for root inventory {root_dir}")

    return True

def validate_version_inventories(self, version_dirs):
    root_inventory_digests = self.get_inventory_digest()  # assuming a method to fetch root inventory digests

    for version_dir in version_dirs:
        inventory_digests = self.get_inventory_digest(version_dir)  # fetch digests for the current version
        if len(inventory_digests) > 0:
            for content_dtct in inventory_digests:
                if content_dtct not in root_inventory_digests:
                    print(f"Found content digest {content_dtct} that differs from_root inventory")
                    return False
    return True

