def size_to_bytes(size: str) -> int:
    unit_to_bytes = {
        "B": 1,
        "KB": 1024,
        "MB": 1024 ** 2,
        "GB": 1024 ** 3,
        "TB": 1024 ** 4
    }

    if not size:
        raise ValueError("Size must be a string")

    if not any(size.endswith(unit) for unit in unit_to_bytes):
        raise ValueError("Invalid unit in size")

    size_number = float(size[:-2])
    unit = size[-2:]

    return int(size_number * unit_to_bytes[unit])

