def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated string.

    :param parser: The argparse.ArgumentParser instance
    :return: A space-separated string of argument flags
    """
    # Initialize the list of argument flags
    argument_flags = []

    # Add all non-positional arguments and their flags
    for action in parser._actions:
        if not action.metavar:
            argument_flags.append('--' + action.dest)

        # Add additional flags for boolean options
        if isinstance(action, argparse.BooleanOptionalAction):
            if action.default == False:
                argument_flags.append('--' + action.dest)

    # Join the argument flags with spaces and return
    return ' '.join(argument_flags)

