def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """

    if number == 0:
        return "0"

    try:
        str_num = ""
        while number > 0:
            digit = number % len(alphabet)
            str_num = alphabet[digit] + str_num
            number //= len(alphabet)

        if padding is not None:
            str_num = (str_num.zfill(padding) if len(str_num) < padding else str_num)

        return str_num
    except Exception as e:
        # Handle potential invalid inputs and runtime issues with exception-handling behavior as appropriate
        raise ValueError("Invalid input") from e

