        return re.split(r' ', s)
    elif platform == '2':
        return re.split(r' |-', s)
    else:
        return []

import re

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform.lower() == 'this':
        platform = platform
    elif platform == 1:
        platform = 'posix'
    elif platform == 0:
        platform = 'cmd'
    else:
        raise ValueError("Invalid platform value")

    if platform == 'posix':
        # Use the POSIX-specific command-line splitting
        return re.split(r'[ \t\n]', s)
    elif platform == 'cmd':
        # Use the Windows/CMD-specific command-line splitting
        return re.split(r'[ " "', r'\t\n]', s)
    else:
        # Default to splitting with space
        return s.split()

