def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    try:
        if filename is None:
            filename = archive_path.split("/")[-1]
        subprocess.run(f"tar -xvf {archive_path}", check=True, capture_output=False, text=True)
        repo_path = shutil.unpack_archive(archive_path, tmp_path)[0]
        origin_url = f"file://{repo_path}"
        return origin_url
    except FileNotFoundError:
        raise FileNotFoundError(f"No such file: {archive_path}")
    except subprocess.CalledProcessError:
        raise subprocess.CalledProcessError(f"Failed to extract archive from {archive_path}")
    except Exception as e:
        raise Exception(f"An error occurred: {e}")

import subprocess
from typing import Optional, Union

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not isinstance(archive_path, str):
        raise ValueError("archive_path should be a string")

    if tmp_path is not None and not isinstance(tmp_path, (str, PosixPath)):
        raise ValueError("tmp_path should be a string or PosixPath")

    if filename is None:
        filename = archive_path.rsplit('/', 1)[-1]

    uncompress_command = [
        "unzip",
        archive_path,
        "-d",
        tmp_path,
    ]

    if filename:
        uncompress_command.extend(["-n", filename])

    try:
        subprocess.run(uncompress_command, check=True)
        return f"https://github.com/user/file?filename={filename}"
    except subprocess.CalledProcessError as e:
        raise ValueError(f"Failed to uncompress archive: {e}")

