    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    if not archive_path or not Path(archive_path).is_file():
        raise ValueError("Invalid archive path")

    if filename:
        archive_path = Path(archive_path) / filename

    try:
        subprocess.run(["tar", "-xzf", archive_path], cwd=tmp_path, check=True)
        repo_url = f"file://{str(Path(tmp_path) / archive_path.name)}"
        return repo_url
    except subprocess.CalledProcessError:
        raise Exception("Failed to extract archive")
