        full_cmd.append(f'-c "export {" ".join(full_env)}"')

    # Execute the command
    try:
        result = subprocess.run(full_cmd, check=True, stdout=None if verbose else subprocess.PIPE, stderr=None if hide_stderr else subprocess.PIPE, env=env, text=True)
        return result.stdout if verbose else None
    except subprocess.CalledProcessError as e:
        if verbose:
