    if not isinstance(prop, rdflib.URIRef):
        raise ValueError("Second argument must be a rdflib.URIRef")

    if roots is None:
        roots = set()

    visited = set()
    stack = [(node, prop) for node in graph.subjects(property=prop)]
    while stack:
        node, prop = stack.pop()
        if node in visited:
