            return

        visited.add(node)
        # Check if the node has the property at the current depth
        for child in graph.subjects predicate=prop, object=node):
            dfs(child)

    # Start DFS from each subject (root) in the graph
    for subject in graph.subjects(predicate=rdflib.RDFS.subClassOf):
        if subject not in visited:
            dfs(subject)

