def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    if other is None:
        return self.scale
    else:
        if self.scale == 0:
            raise LenaValueError("Cannot rescale graph with unknown or zero scale")
        else:
            for field in self.graph_fields:
                if hasattr(self, field):
                    setattr(self, field, getattr(self, field) / self.scale * other)

def scale(self, other=None):
        if other is None:
            # Check if the graph has a valid scale
            if self.scale is None or self.scale == 0:
                raise LenaValueError("Graph has unknown or zero scale")
            return self.scale
        else:
            # Resize the scale using the provided value
            if other <= 0:
                raise ValueError("Scale must be positive")
            self.scale = other

def scale(self, other=None):
    if other is None:
        return self.scale
    elif isinstance(other, (int, float)):
        if self.scale == 0:
            raise LenaValueError("Cannot rescale graph with zero scale")
        self.scaling_map = lambda x: x * other
    else:
        raise ValueError("Scale must be None, an integer or a float")

def scale(self, other=None):
    if other is None:
        return self.scale
    else:
        if isinstance(other, (int, float)):
            scale = other
        else:
            raise LenaValueError("Scale must be a numeric value")
        # Assuming self._fields contains lists of coordinates
        for coord in self._fields:
            try:
                coord[-1] *= scale
            except IndexError:
                raise LenaValueError("Invalid scale: graph has unknown or zero scale")
        return scale

